from hypothesis import given, strategies as st

from solution import Service


class FakeClock:
    def __init__(self, t=0.0):
        self.t = float(t)

    def now(self):
        return self.t


def assert_response(out, expected_status, inp):
    assert isinstance(out, tuple) and len(out) == 2, f"input={inp!r} output={out!r}"
    status, body = out
    assert isinstance(status, int), f"input={inp!r} output={out!r}"
    assert body is None or isinstance(body, (dict, list)), f"input={inp!r} output={out!r}"
    assert status == expected_status, f"input={inp!r} output={out!r}"
    return body


def test_default_max_loans_allows_three_active_loans_and_rejects_the_fourth():
    """With default configuration, checkout must allow at most three simultaneous active loans per user."""
    svc = Service(FakeClock())
    inp = {"scenario": "default max_loans is exactly 3"}

    assert_response(svc.register_user("u", "member"), 201, inp)
    for item_id in ["i1", "i2", "i3", "i4"]:
        assert_response(svc.add_item(item_id, f"Item {item_id}"), 201, inp)

    for expected_id, item_id in enumerate(["i1", "i2", "i3"], start=1):
        out = svc.checkout("u", item_id)
        body = assert_response(out, 200, inp)
        assert body == {"loan_id": expected_id, "due_at": 7.0}, (
            f"input={inp!r} output={out!r}"
        )

    out = svc.checkout("u", "i4")
    assert_response(out, 422, inp)

    out = svc.list_loans("u")
    body = assert_response(out, 200, inp)
    active = [loan for loan in body if loan["status"] == "active"]
    assert len(active) == 3, f"input={inp!r} output={out!r}"


@given(
    user_id=st.text(min_size=1, max_size=10),
    item_ids=st.lists(st.text(min_size=1, max_size=10), min_size=4, max_size=4, unique=True),
)
def test_default_max_loans_is_three_for_all_valid_users_and_items(user_id, item_ids):
    """The default max_loans limit must be three active loans for any valid registered user and valid catalog items."""
    svc = Service(FakeClock())
    inp = {"user_id": user_id, "item_ids": item_ids}

    assert_response(svc.register_user(user_id, "member"), 201, inp)
    for idx, item_id in enumerate(item_ids):
        assert_response(svc.add_item(item_id, f"Item {idx}"), 201, inp)

    for idx, item_id in enumerate(item_ids[:3], start=1):
        out = svc.checkout(user_id, item_id)
        body = assert_response(out, 200, inp)
        assert body == {"loan_id": idx, "due_at": 7.0}, (
            f"input={inp!r} output={out!r}"
        )

    out = svc.checkout(user_id, item_ids[3])
    assert_response(out, 422, inp)
